let myIterableObj = { 
  [Symbol.iterator]: function* () {
    yield 1; yield 2; yield 3;
  }
};
console.log([...myIterableObj]); // [ 1, 2, 3 ]

function* idMaker() {
  let index = 0;
  while (index < 5)
    yield index++;
}
var gen = idMaker();

console.log(gen.next().value);
console.log(gen.next().value);
console.log(gen.next().value);
console.log(gen.next().value);
console.log(gen.next().value);
// 尝试添加更多的 console.log, 看看会发生什么.

const arr = ['0', '1', '4', 'a', '9', 'c', '16'];
const my_obj = {
  [Symbol.iterator]: function*() {
    for(let index of arr) {
      yield `${index}`;
    }
  }
};

const all = [...my_obj] /* 可以用 'arr' 替换 '[...my_obj]' */
  .map(i => parseInt(i, 10))
  .map(Math.sqrt)
  .filter((i) => i < 5) /* 尝试将 5 改为 4，看看将发生什么 */
  .reduce((i, d) => i + d); /* 改变上一行的值后，注释掉该行 */

console.log(all);

